package io.github.hoangtnedu.java.customer;
import io.github.hoangtnedu.java.orders.*;import jakarta.servlet.*;import jakarta.servlet.annotation.*;import jakarta.servlet.http.*;import java.io.*;import java.util.*;
@WebServlet("/orders") public class OrdersServlet extends HttpServlet {private CustomerService service;
 public void init()throws ServletException{try{Database.init();service=new CustomerService();}catch(Exception e){throw new ServletException(e);}}
 public void destroy(){if(service!=null)service.close();}
 private Database.User user(HttpServletRequest q)throws Exception{String auth=q.getHeader("Authorization");if(auth!=null&&auth.startsWith("Basic ")){String[] v=new String(Base64.getDecoder().decode(auth.substring(6)),java.nio.charset.StandardCharsets.UTF_8).split(":",2);if(v.length==2)return Database.authenticate(v[0],v[1]);}return (Database.User)q.getSession().getAttribute("user");}
 protected void doGet(HttpServletRequest q,HttpServletResponse r)throws IOException{r.setContentType("text/html;charset=UTF-8");try{Database.User u=user(q);if(u==null||!"CUSTOMER".equals(u.role())){r.setStatus(401);r.setHeader("WWW-Authenticate","Basic realm=HoangTN-local-lab");return;}String csrf=(String)q.getSession().getAttribute("csrf");if(csrf==null){csrf=UUID.randomUUID().toString();q.getSession().setAttribute("csrf",csrf);}r.setHeader("X-CSRF-Token",csrf);var out=r.getWriter();out.print("<!doctype html><html><head><meta charset='utf-8'><title>Customer Portal</title></head><body><h1>HoangTN Customer Portal</h1><form method='post'><input type='hidden' name='csrf' value='"+csrf+"'><input name='product' type='number' required placeholder='Product ID'><input name='quantity' type='number' min='1' required><button name='action' value='create'>Create order</button></form><table>");for(Order o:service.list(u.id()))out.print("<tr><td>"+o.id+"</td><td>"+o.status+"</td><td><form method='post'><input type='hidden' name='csrf' value='"+csrf+"'><input type='hidden' name='id' value='"+o.id+"'><button name='action' value='complete'>Confirm received</button></form></td></tr>");out.print("</table></body></html>");}catch(Exception e){r.sendError(400);}}
 protected void doPost(HttpServletRequest q,HttpServletResponse r)throws IOException{try{Database.User u=user(q);if(u==null||!"CUSTOMER".equals(u.role())){r.sendError(403);return;}if(q.getSession().getAttribute("csrf")==null||!Objects.equals(q.getSession().getAttribute("csrf"),q.getParameter("csrf"))){r.sendError(403);return;}if("complete".equals(q.getParameter("action"))){service.complete(u,Long.parseLong(q.getParameter("id")));r.getWriter().print("COMPLETED");}else{long id=service.create(u,Long.parseLong(q.getParameter("product")),Integer.parseInt(q.getParameter("quantity")));r.setStatus(201);r.setHeader("X-Order-Id",Long.toString(id));r.getWriter().print(id);}}catch(Exception e){r.sendError(409);}}
}